package dev.zomboid.firstaid;
import java.util.*;
public class RevivalChecks {
 static int cases;static void check(boolean b){cases++;if(!b)throw new AssertionError(cases);}
 public static class Tag {final Map<String,Boolean> b=new HashMap<>();public void putBoolean(String k,boolean v){b.put(k,v);}public boolean getBoolean(String k){return b.getOrDefault(k,false);}}
 public static class Random {final double[] rolls;int i;Random(double...r){rolls=r;}public double nextDouble(){return rolls[i++];}}
 public static class World {public boolean client;public boolean isClientSide(){return client;}}public static class Player {public final World world=new World();public World level(){return world;}public int fitness;public void displayClientMessage(Object text,boolean actionbar){}final Tag tag=new Tag();final Random random;Player(double...r){random=new Random(r);}public float getMaxHealth(){return 20;}public boolean isAlive(){return true;}public Tag getPersistentData(){return tag;}public Random getRandom(){return random;}}
 public static class Model extends Checks.Model {public int unconsciousTicks,rescues;public String reason;public Model(){for(int i=0;i<8;i++)add(new Checks.Part(0));}public void setUnconsciousState(int t,boolean giveUp,boolean death,String reason){unconsciousTicks=t;this.reason=reason;}public void scheduleResync(){}public int getUnconsciousTicks(){return unconsciousTicks;}public boolean rescueFromCriticalState(Object p,Object healer,boolean delay){rescues++;criticalConditionActive=false;for(Checks.Part part:this)part.currentHealth=1;return true;}}
 public static void main(String[] args){Model m=new Model();Player p=new Player(.1,.1);Revival.post(m,p,null);check(Revival.active(m)&&m.unconsciousTicks==2400);check(m.reason.equals("firstaid.gui.downed_25"));check(!ZeroParts.dead(m,p)&&ZeroParts.health(m,p)==1);Revival.post(m,p,null);check(p.random.i==2);m.unconsciousTicks=2201;Revival.tick(m,p);check(m.rescues==0);m.unconsciousTicks=2200;Revival.tick(m,p);check(m.rescues==1&&!Revival.active(m)&&ZeroParts.health(m,p)>0);Revival.tick(m,p);check(m.rescues==1);Model fatal=new Model();Player unlucky=new Player(.99);Revival.post(fatal,unlucky,null);check(!Revival.active(fatal)&&ZeroParts.dead(fatal,unlucky));Model hurt=new Model();hurt.get(0).currentHealth=1;Revival.post(hurt,new Player(),null);check(!Revival.active(hurt));Model failed=new Model();Player needsHelp=new Player(.1,.3);Revival.post(failed,needsHelp,null);failed.unconsciousTicks=2200;Revival.tick(failed,needsHelp);check(Revival.active(failed)&&failed.rescues==0&&needsHelp.tag.getBoolean("FARevivalAttempted"));Revival.tick(failed,needsHelp);check(needsHelp.random.i==2&&failed.rescues==0);Model fit=new Model();Player runner=new Player(.1,.4);runner.fitness=10;Revival.post(fit,runner,null);check(fit.reason.equals("firstaid.gui.downed_45")&&runner.tag.getBoolean("FARevivalSuccess"));fit.unconsciousTicks=2200;Revival.tick(fit,runner);check(fit.rescues==1);Model clientModel=new Model();Player client=new Player();client.world.client=true;Revival.post(clientModel,client,null);check(!Revival.active(clientModel)&&client.random.i==0);System.out.println(cases+" simulated revival lifecycle cases passed");}
}
